export type EnsureThreadReply = { thread: ConversationThread, created: boolean, notices: Array<string>, };

export type EnsureThreadRequest = { title: string, selected_model: string, model_order: Array<string>, profile: string, collection: string, initial_instruction: string, instructions: string, };

export type ErrorCode = "invalid_request" | "not_found" | "invalid_app_definition" | "unsupported_app" | "permission_denied" | "not_granted" | "path_outside_root" | "conflict" | "login_required" | "binding_conflict" | "io" | "server" | "unavailable" | "local_agent_failed";

export type ExecutionConsent = { spec_hash: string, name: string, command: string, args: Array<string>, env: { [key in string]: string }, };

/**
 * (블록 세트 5판) 탐색기 오른쪽 칸의 보기 방식. 창 상태에는 이 문자열로 둔다.
 */
export type ExplorerView = "icons" | "details";

/**
 * 식 바인딩. 예: `{ "expr": "$data.cards.cards[status = 'running']" }`.
 */
export type ExprRef = { expr: string, };

export type ExternalKey = { namespace: string, key: string, };

export type FeedBody = string | Array<string>;

/**
 * `feed` 항목. 이름(색과 초상)과 본문 줄들. 본문은 줄바꿈을 지키고 글을 고르고 복사할 수 있다.
 */
export type FeedEntry = { key: string, name?: string, 
/**
 * 이름의 색(`#rrggbb`).
 */
color?: string, 
/**
 * 이름 옆의 작은 원형 초상.
 */
image?: MediaRef, meta?: string, 
/**
 * 본문. 문자열 하나나 문자열 배열(문단마다 하나, 예: 한국어와 영어).
 */
body: FeedBody, tone?: Tone, };

/**
 * 속성 값을 보이는 방법.
 */
export type FieldFormat = "text" | "markdown" | "badge" | "date" | "code";

export type FileAccess = "read" | "readwrite";

/**
 * 폴더 안 항목 하나.
 */
export type FileEntry = { name: string, 
/**
 * 고른 폴더 기준 상대 경로.
 */
path: string, kind: FileKind, 
/**
 * (8판) 파일 크기(바이트). 폴더는 0.
 */
size: number, 
/**
 * (8판) 마지막으로 바뀐 시각(RFC 3339 UTC, 초까지, 예: `2026-10-30T01:02:03Z`). 읽지 못하면 빈 문자열.
 */
modified: string, 
/**
 * (계약 14판) `scope: pc`의 내 PC 목록(빈 경로)에서만 붙는 뿌리의 종류. 그때 `path`는 뿌리의 id이고
 * `name`은 뿌리의 화면 이름, `kind`는 `dir`, `size`는 0, `modified`는 빈 문자열이다.
 */
root_kind?: PcRootKind, };

export type FileKind = "file" | "dir";

/**
 * 권한 하나의 폴더 안 파일 하나.
 *
 * 경로 규칙(정의에 적은 경로와 `files.*` 명령의 경로 모두):
 * - 고른 폴더 기준 상대 경로이고 이름들을 `/`로 잇는다. 앞뒤에 `/`를 두지 않는다.
 * - 이름은 비어 있지 않고 `.`, `..`가 아니며 `\`, `:`, NUL을 담지 않는다.
 * - 빈 문자열은 폴더 자체이고 `files.list`의 `dir`에서만 쓴다.
 * - 코어는 실행할 때 심볼릭 링크를 풀어 실제 경로가 고른 폴더의 실제 경로 안에 있는지 다시 확인하고,
 *   밖이면 `path_outside_root`로 거부한다.
 */
export type FileRef = { permission: string, path: PathValue, };

/**
 * (모듈 `files` 2판) `files` 권한이 가리키는 범위.
 *
 * `pc`의 규칙:
 * - 읽기 전용이다(`access: read`). 지금은 `explorer` 블록의 `root`만 이 권한을 가리킬 수 있다(검사기가 거부).
 * - 이 기기에서 이 앱에 처음 쓸 때 허용을 받는다(`files.allow_pc`). 허용 전의 `files.list`와 `files.open`은 `not_granted`다.
 * - `pc` 권한으로는 `files.list`와 `files.open`만 한다. `files.read`는 `not_granted`, `files.write`는
 *   `permission_denied`이고 파일 내용은 여는 앱이 넘겨받은 폴더로 읽는다.
 * - 경로의 첫 마디는 뿌리의 id([`PcRootKind`])이고 그 아래는 [`FileRef`]의 경로 규칙을 따른다. 빈 경로는 내 PC 자체이고
 *   `files.list`는 뿌리들을 낸다(알려진 폴더 먼저, 그다음 볼륨, 각각 이 기기가 준 순서). 뿌리에 없는 첫 마디는
 *   `not_found`다. 창 상태에 이 경로를 두므로 다른 PC에서도 같은 알려진 폴더 아래를 연다(없으면 `not_found`).
 * - 코어는 이 쉘 자신의 데이터 폴더(기기 토큰, 로그인 정보) 안을 가리키는 경로를 `permission_denied`로 거부하고,
 *   목록에서도 뺀다. 이 규칙은 `folder` 범위와 탐색기가 열며 넘겨준 폴더에도 같다.
 * - Windows에서는 숨김이나 시스템 속성이 있는 항목을 목록에서 뺀다(`$Recycle.Bin`, `System Volume Information`,
 *   `pagefile.sys`, 문서 폴더의 `My Music` 같은 연결점). 이 규칙은 `folder` 범위의 목록에도 같다.
 * - 탐색기가 이 범위의 파일을 열면(`files.open`) 여는 앱의 창에는 그 파일이 든 폴더를 고른 것으로 두고, 경로는
 *   파일 이름이다. 여는 앱은 PC 전체를 받지 않는다.
 */
export type FilesScope = "folder" | "pc";

/**
 * `folder` 원천의 항목.
 */
export type FolderEntry = { name: string, 
/**
 * 고른 폴더 기준 상대 경로.
 */
path: string, kind: FileKind, 
/**
 * 확장자(점 없이, 소문자). 없으면 빈 문자열.
 */
ext: string, 
/**
 * 파일 크기(바이트). 폴더는 0.
 */
size: bigint, 
/**
 * 마지막으로 바뀐 시각(RFC 3339 UTC).
 */
modified: string, };

/**
 * 권한 하나가 가리키는 폴더(고른 폴더 자체).
 */
export type FolderRef = { permission: string, };

/**
 * `stack`의 자식 사이 간격. 쉘의 간격 토큰 가운데 하나다.
 */
export type Gap = "none" | "small" | "medium" | "large";

/**
 * 이 기기에서 앱 창의 권한 하나에 고른 폴더. 기기 밖으로 나가지 않는다.
 */
export type Grant = { window_id: string, 
/**
 * 앱 정의의 권한 `id`.
 */
permission: string, 
/**
 * 고른 폴더의 절대 경로(이 기기의 표기 그대로).
 */
root_path: string, 
/**
 * 고른 폴더의 이름. 화면에 보일 때 쓴다.
 */
root_name: string, granted_at: string, };

/**
 * 묶음 하나(`grouped`인 `list`와 `feed`). 머리에 제목과 부가 정보(개수 등)를 보인다.
 */
export type Group<T> = { title: string, meta?: string, items: Array<T>, };

export type HttpMethod = "GET" | "POST" | "PUT" | "PATCH" | "DELETE";

export type ImageFit = "contain" | "cover";

export type InputKind = "text" | "search" | "number";

export type JsonValueType = "object" | "array" | "string" | "number" | "integer" | "boolean" | "null";

/**
 * 이 기기와 오케스트레이터의 연결 상태. `state`로 가른다.
 *
 * 흐름: `unlinked` → (`link.start`) `pairing` → (에이전트가 코드를 승인) `connected` ⇄ `offline`.
 * 승인 전에 코드가 만료되거나 `link.cancel`이면 `unlinked`로 돌아간다. 서버가 기기 토큰을 거부하면
 * `revoked`이고, 다시 `link.start`로 연결한다. `link.unlink`는 어느 상태에서든 `unlinked`로 간다.
 */
export type LinkStatus = { "state": "unlinked", } | { "state": "pairing", server_url: string, 
/**
 * 사람이 읽고 에이전트에게 전하는 코드. 예: `K7PQ-4XMR`.
 */
user_code: string, expires_at: string, } | { "state": "connected", server_url: string, device_name: string, } | { "state": "offline", server_url: string, device_name: string, 
/**
 * 마지막으로 실패한 까닭. 사람이 읽는 한국어 한 줄.
 */
reason: string, } | { "state": "revoked", server_url: string, };

/**
 * `list` 항목.
 */
export type ListItem = { 
/**
 * 고르기와 비교에 쓰는 열쇠. 목록 안에서 겹치지 않는다. 고르면 `$event`가 이 값이다.
 */
key: string, title: string, subtitle?: string, 
/**
 * 오른쪽에 작게 보이는 부가 정보(시각, 개수).
 */
meta?: string, 
/**
 * 항목의 표시 색(`#rrggbb`). 앞의 점이나 막대로 보인다.
 */
color?: string, badges?: Array<Badge>, 
/**
 * 줄 보기에서는 앞의 작은 그림, 격자 보기에서는 칸의 그림.
 */
image?: MediaRef, };

export type ListLayout = "rows" | "grid";

export type LocalAgentAccess = { app_id: string, permission: string, spec_hash: string, granted_at: string, };

export type LocalAgentPhase = "choosing_agent" | "choosing_folder" | "awaiting_permission" | "starting" | "login_required" | "ready" | "responding" | "failed" | "ended";

export type LocalAgentSnapshot = { generation: string, phase: LocalAgentPhase, agents: Array<AgentChoice>, selected: string | null, folder_name: string | null, execution: ExecutionConsent | null, auth_methods: Array<AuthChoice>, controls: Array<AgentControl>, history: Array<ConversationItem>, stream_id: string | null, text: string, activity: AgentActivity, permissions: Array<PermissionPrompt>, queued: Array<QueuedMessage>, failure: AgentFailure | null, };

export type LocalAgentUpdate = { "type": "snapshot", snapshot: LocalAgentSnapshot, } | { "type": "conversation", update: ConversationEvent, } | { "type": "state", phase: LocalAgentPhase, controls: Array<AgentControl>, auth_methods: Array<AuthChoice>, execution: ExecutionConsent | null, failure: AgentFailure | null, } | { "type": "permissions", permissions: Array<PermissionPrompt>, } | { "type": "queue", queued: Array<QueuedMessage>, };

/**
 * `data.media` 응답의 내용.
 */
export type MediaData = { mime: string, 
/**
 * 표준 base64.
 */
data_base64: string, 
/**
 * 이미지면 보내는 그림의 가로와 세로(px). 소리와 영상은 null.
 */
width: number | null, height: number | null, };

export type MediaKind = "audio" | "video";

/**
 * 이미지와 소리 원본 하나. 식이 이 모양의 객체를 내면 블록이 `data.media`로 받아 그린다.
 * `permission`의 모듈이 `connection`이면 `path`는 연결의 주소 아래 경로(`/`로 시작)이고 `query`를 붙인다.
 * `files`면 `path`는 고른 폴더 기준 상대 경로다. `crop`은 그리는 방법이라 원본을 가르지 않는다.
 */
export type MediaRef = { permission: string, path: string, query?: { [key in string]: string }, crop?: Crop, };

export type MessageReceipt = { request_id: string, status: ReceiptStatus, error?: ConversationError, };

export type ModelsReply = { models: Array<ConversationModel>, };

/**
 * 앱이 여는 파일의 선언. 예: `{ "extensions": ["md"], "permission": "docs", "state": "current_file" }`.
 */
export type OpensDecl = { 
/**
 * 여는 파일 확장자(점 없이, 소문자). 하나 이상.
 */
extensions: Array<string>, 
/**
 * 탐색기의 폴더를 이어 받을 `files` 권한 id. 파일을 열면 이 권한에 탐색기와 같은 폴더를 고른 것이 된다.
 */
permission: string, 
/**
 * 연 파일의 경로(그 폴더 기준 상대 경로)를 쓸 상태 키. 블록은 이 키로 그 파일을 연다.
 */
state: string, };

export type PatchThreadRequest = { title?: string, archived?: boolean, model?: string, model_order?: Array<string>, instructions?: string, };

/**
 * 경로 값. 창 상태에서 읽거나(`{ "state": "current_file" }`) 정의에 직접 적는다(`"notes/todo.md"`).
 * 상태 값이 null이거나 문자열이 아니면 열 파일이 없는 것이다.
 */
export type PathValue = StateRef | string;

/**
 * (계약 14판) 이 기기에서 앱 하나의 `scope: pc` 권한 하나를 허용한 기록. 기기 밖으로 나가지 않는다.
 */
export type PcAccess = { app_id: string, 
/**
 * 앱 정의의 권한 `id`.
 */
permission: string, granted_at: string, };

/**
 * (계약 14판) 내 PC 뿌리의 종류. 뿌리 하나는 id(경로의 첫 마디), 종류, 화면 이름, 이 기기의 절대 경로이고,
 * 코어의 호스트가 이 기기에서 찾아 준다(절대 경로는 화면과 서버에 보내지 않는다).
 * - 알려진 폴더: id는 [`PC_KNOWN_FOLDERS`]의 id, 이름은 그 표의 이름.
 * - 볼륨: Windows는 id가 드라이브 글자 하나(대문자, 예: `C`)이고 이름은 「볼륨 이름 (C:)」, 볼륨 이름이 없으면
 *   「로컬 디스크 (C:)」다.
 */
export type PcRootKind = "known" | "volume";

export type PermissionChoice = { id: string, label: string, kind: string, };

/**
 * 앱이 쓰겠다고 선언하는 권한. 실제로 허락하는 것은 기기마다 사용자다.
 */
export type PermissionDecl = { "module": "files", id: string, access: FileAccess, 
/**
 * 폴더를 고르라고 할 때 보일 이름(예: "문서 폴더"). `scope: pc`면 탐색기 경로의 맨 앞 마디 이름(예: "내 PC").
 */
label: string, 
/**
 * (모듈 `files` 2판) 없으면 `folder`다.
 */
scope?: FilesScope, } | { "module": "connection", id: string, 
/**
 * 서버에 등록한 연결 이름(소문자, 숫자, `-` 1~64자).
 */
connection: string, access: FileAccess, 
/**
 * 로그인을 구할 때와 오류에 보일 이름(예: "카드 보드").
 */
label: string, } | { "module": "local_agent", id: string, label: string, };

export type PermissionPrompt = { id: string, title: string, options: Array<PermissionChoice>, };

/**
 * 속성 한 줄.
 */
export type PropertyField = { label: string, value: Binding, format?: FieldFormat, };

export type QueuedMessage = { id: string, text: string, attachments: Array<ConversationAttachment>, };

export type ReceiptStatus = "accepted" | "failed" | "pending";

export type Rect = { x: number, y: number, width: number, height: number, };

/**
 * 원천을 다시 받는다. 빈 배열이면 모든 원천이다. 받기를 마칠 때까지 기다린다(실패해도 동작은 이어 간다).
 */
export type RefreshAction = { refresh: Array<string>, };

/**
 * 앱이 필요로 하는 블록 세트와 모듈의 버전.
 */
export type Requires = { blocks: number, modules: { [key in string]: number }, };

/**
 * `select`의 선택지. 문자열만 쓰면 값과 이름이 같다.
 */
export type SelectOption = string | { value: JsonValue, label: string, };

export type SelectStyle = "dropdown" | "segmented";

export type SendMessageRequest = { request_id: string, text: string, attachments: Array<ConversationUpload>, context?: string, };

/**
 * 블록 이벤트의 값을 창 상태 키 하나에 쓴다. 예: `{ "set_state": "current_file" }`.
 */
export type SetState = { set_state: string, };

/**
 * 창 상태 키 하나에 값을 쓴다. `value`를 빼면 `$event`를 쓴다. `"value": null`은 null을 쓴다(상태 비우기).
 * 예: `{ "set_state": "file", "value": { "expr": "$item.file" } }`, `{ "set_state": "conversation", "value": null }`.
 */
export type SetStateAction = { set_state: string, 
/**
 * 빠졌으면 None, 적혀 있으면 null이어도 `Some(Binding::Literal(null))`이다.
 */
value?: Binding, };

/**
 * 저장소 항목 하나에 값을 쓴다. 예: `{ "set_storage": { "entry": "selection", "value": { "expr": "$event" } } }`.
 */
export type SetStorageAction = { set_storage: SetStorageSpec, };

export type SetStorageSpec = { entry: string, 
/**
 * 빠졌으면 `$event`, 적혀 있으면 null도 값이다.
 */
value?: Binding, };

/**
 * 기기 사이에 맞출 상태. 2단계 동기화의 단위다.
 */
export type SharedState = { apps: Array<App>, app_versions: Array<AppVersion>, workspaces: Array<Workspace>, desktops: Array<Desktop>, windows: Array<AppWindow>, };

/**
 * 화면이 보는 상태 전체.
 */
export type ShellSnapshot = { shared: SharedState, device: DeviceState, supported: Supported, link: LinkStatus, 
/**
 * (9판) 이 기기에서 같이 보기를 켠 창의 id. 켠 순서다. 코어의 메모리에만 있어 쉘을 다시 켜면 빈 목록이다.
 */
sharing: Array<string>, 
/**
 * (10판) 이 쉘 자신의 새 판 받기 상태. 코어의 메모리에만 있다.
 */
update: UpdateStatus, };

export type SortSpec = { field: string, desc?: boolean, };

/**
 * 원천 하나. `kind`로 가른다. 이름은 소문자로 시작하고 소문자, 숫자, `_`로 1~32자다(식에서 `$data.이름`으로 읽는다).
 * 값 자리([`Binding`])의 식은 `$state`만 본다. 값이 null이면 그 원천을 부르지 않는다(`idle`).
 */
export type SourceDecl = { "kind": "request", permission: string, path: Binding, query?: { [key in string]: Binding }, format?: SourceFormat, refresh_secs?: number, } | { "kind": "file", permission: string, path: Binding, format?: SourceFormat, refresh_secs?: number, } | { "kind": "folder", permission: string, dir?: Binding, recursive?: boolean, extensions?: Array<string>, refresh_secs?: number, };

/**
 * 원천이 받은 것을 읽는 방법.
 */
export type SourceFormat = "json" | "text";

/**
 * 원천 하나의 상태. `state`로 가른다.
 */
export type SourceStatus = { "state": "idle", } | { "state": "loading", has_value: boolean, } | { "state": "ready", updated_at: string, } | { "state": "failed", message: string, has_value: boolean, } | { "state": "login_required", permission: string, };

export type SplitDirection = "row" | "column";

/**
 * 창 상태 키 하나를 읽는다. 예: `{ "state": "current_file" }`.
 */
export type StateRef = { state: string, };

/**
 * 항목이 바뀌었을 때 보내는 메타데이터. 저장 본문은 이벤트에 실리지 않는다.
 */
export type StorageChanged = { bucket_id: string, item: StorageItemMeta, };

/**
 * 설정 선택지 하나. 문자열은 값과 라벨을 겸하고 객체는 별도 라벨을 제공한다.
 */
export type StorageChoice = string | StorageChoiceObject;

export type StorageChoiceObject = { value: string, label?: string, };

export type StorageConflict = { current_revision: string | null, };

/**
 * 앱 정의가 저장소에 선언하는 항목 모음.
 */
export type StorageDecl = { entries: Array<StorageEntryDecl>, };

/**
 * 앱 정의의 저장 항목. JSON 항목은 제한된 JSON Schema와 JSON 기본값을, md 항목은 문자열 기본값을 가진다.
 */
export type StorageEntryDecl = { id: string, 
/**
 * 계정 × 앱 bucket 안의 키. 유일한 치환자는 `{workspace_id}`다.
 */
key: string, kind: StorageKind, schema?: StorageValueSchema, 
/**
 * JSON 값 또는 UTF-8 Markdown 문자열.
 */
default: JsonValue, label: string, description?: string, presentation: StoragePresentation, choices?: Binding, agent_context?: boolean, };

/**
 * 저장소 항목 하나의 메타데이터. 이벤트와 목록 응답에는 본문을 넣지 않는다.
 */
export type StorageItemMeta = { entry_id: string, key: string, kind: StorageKind, revision: string | null, exists: boolean, };

export type StorageKind = "json" | "md";

export type StorageListReply = { bucket_id: string, items: Array<StorageItemMeta>, };

export type StoragePresentation = "settings" | "hidden";

/**
 * `content`는 JSON kind에서 임의 JSON, md kind에서 문자열이다.
 */
export type StorageReadReply = { kind: StorageKind, content: JsonValue, revision: string | null, exists: boolean, };

export type StorageResetReply = { revision: string | null, };

export type StorageResetRequest = { expected_revision?: ExpectedRevision, };

export type StorageSchemaType = JsonValueType | Array<JsonValueType>;

/**
 * 저장소 상태가 연결되었을 때 보내는 메타데이터 snapshot.
 */
export type StorageSnapshot = { bucket_id: string, items: Array<StorageItemMeta>, };

export type StorageUpdate = { "kind": "snapshot", snapshot: StorageSnapshot, } | { "kind": "changed", changed: StorageChanged, };

/**
 * storage 값 검사가 지원하는 JSON Schema 부분집합. 알 수 없는 키는 serde가 거부한다.
 */
export type StorageValueSchema = { type: StorageSchemaType, properties?: { [key in string]: StorageValueSchema }, required?: Array<string>, additionalProperties?: boolean, items?: StorageValueSchema, enum?: Array<JsonValue>, uniqueItems?: boolean, minLength?: number, };

export type StorageWriteReply = { revision: string, };

export type StorageWriteRequest = { content: JsonValue, expected_revision?: ExpectedRevision, };

/**
 * 이 쉘이 지원하는 블록 세트와 모듈의 버전.
 */
export type Supported = { blocks: number, modules: { [key in string]: number }, };

/**
 * 탭 하나.
 */
export type Tab = { label: string, child: Block, };

export type TextFormat = "plain" | "markdown";

/**
 * 글의 크기와 결. 쉘의 글자 토큰 가운데 하나다.
 */
export type TextStyle = "body" | "title" | "meta";

export type ThreadByKeyReply = { thread: ConversationThread, };

export type ThreadInfoReply = { thread: ConversationThread, busy: boolean, tool: string | null, current_model: ThreadModel | null, };

export type ThreadItemsReply = { 
/**
 * 기본값은 200, 요청 상한도 200이다. 더 읽을 때는 `next_before`를 쓴다.
 */
items: Array<ConversationItem>, next_before?: string, cursor: string, };

export type ThreadListReply = { refs: Array<ThreadRef>, next_cursor?: string, };

export type ThreadModel = { id: string, label: string, };

export type ThreadRef = { id: string, title: string, created_at: string, archived: boolean, };

export type ThreadSnapshot = { cursor: string, busy: boolean, tool: string | null, stream_id: string | null, text: string | null, items: Array<ConversationItem>, };

/**
 * 글의 결. `muted`는 눈에 덜 띄게, `error`는 오류 색으로.
 */
export type Tone = "default" | "muted" | "error";

export type TreeBy = "children" | "path";

/**
 * `tree` 항목. `by: children`이면 `children`으로 내려가고, `by: path`면 `path`를 `/`로 나눠 폴더를 만든다.
 */
export type TreeItem = { key: string, 
/**
 * 없으면 `path`의 마지막 이름이다.
 */
title?: string, path?: string, meta?: string, badges?: Array<Badge>, children?: Array<TreeItem>, };

/**
 * (10판) 이 쉘 자신의 새 판 받기 상태. `state`로 가른다. 위 「쉘 업데이트」 절.
 *
 * 흐름: `idle` → (새 판이 있음) `downloading` → (받고 서명 확인) `ready` → (`update.restart`) 쉘이 끝나고 새 판이 뜬다.
 * 묻기, 받기, 서명 확인, 설치 시작 가운데 하나가 실패하면 `failed`이고, 다음 확인 때 처음부터 다시 한다.
 * 화면은 `ready`일 때만 디렉터에게 알린다. 나머지 상태는 보이지 않는다(검증과 진단용).
 */
export type UpdateStatus = { "state": "unavailable", } | { "state": "idle", current_version: string, } | { "state": "downloading", current_version: string, version: string, } | { "state": "ready", current_version: string, version: string, } | { "state": "failed", current_version: string, version: string | null, reason: string, };

/**
 * 주소 값. 창 상태에서 읽거나(`{ "state": "url" }`) 정의에 직접 적는다(`"https://example.com"`).
 * 상태 값이 null이거나 문자열이 아니면 열 주소가 없는 것이다.
 */
export type UrlValue = StateRef | string;

/**
 * (9판) 같이 보기 창에 지금 보이는 것을 화면이 옮긴 것.
 */
export type VisibleView = { 
/**
 * 창의 내용 영역에 보이는 글. 사람과 PAS가 읽는 글이고, 서버는 줄 단위로 앞의 것과 비교한다.
 * 화면이 지키는 모양:
 * - 위에서 아래, 왼쪽에서 오른쪽 순서로 한 줄에 한 덩이를 둔다. 빈 줄은 이어서 두지 않는다.
 * - 블록마다 그 블록을 알리는 머리 줄을 대괄호로 둔다. 예: `[파일 notes/plan.md, 40~78줄 / 전체 210줄]`(편집기와
 *   코드 보기는 그 아래에 보이는 줄의 원문을 그대로 둔다), `[목록, 전체 120개 중 11~30번째]`, `[표, 전체 52줄 중
 *   1~18번째]`(칸은 ` | `로 잇는다), `[웹 화면: 페이지 제목, https://...]`, `[이미지: 설명]`.
 * - 줄 번호는 머리 줄의 범위로만 알리고 줄마다 붙이지 않는다. 줄마다 붙이면 한 줄을 넣거나 지울 때 그 아래 줄이
 *   모두 바뀐 것으로 보여, 서버의 차분이 글 전체가 된다(카드 #814 운영 확인에서 드러남).
 * - 고른 항목은 줄 앞에 `› `, 체크 상자는 `[x] `나 `[ ] `, 입력칸은 `이름: 값`이다.
 * - [`SHARE_TEXT_MAX_BYTES`]를 넘지 않는다.
 */
text: string, 
/**
 * 이미지, 동영상, 그림판, 웹 화면처럼 글로 옮길 수 없는 것이 보이는가. 참이면 `conversation.send` 때 모습을 찍는다.
 */
visual: boolean, 
/**
 * 창의 내용 영역(제목 줄 아래)이 쉘 화면(메인 웹뷰) 왼쪽 위 기준 어디에 있는가(CSS px). 모습을 찍을 때 쓴다.
 */
bounds: Rect, };

export type WebHistoryAction = "back" | "forward" | "reload" | "stop";

/**
 * 웹 화면의 지금 페이지.
 */
export type WebPage = { 
/**
 * 지금 주소. 페이지 안에서만 바뀐 주소(history.pushState)도 포함한다.
 */
url: string, 
/**
 * 문서 제목. 없으면 빈 문자열이고, 화면은 그때 주소의 호스트를 보인다.
 */
title: string, 
/**
 * 페이지를 읽는 중인가.
 */
loading: boolean, can_go_back: boolean, can_go_forward: boolean, };

/**
 * 작업 주제 하나. 데스크톱 여러 장을 가진다.
 */
export type Workspace = { id: string, name: string, created_at: string, updated_at: string, };
